CREATE TABLE work_plan(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,customer_id TEXT NOT NULL,user_id TEXT NOT NULL,scheduled_at TEXT NOT NULL,original_scheduled_at TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('visit','call')),status TEXT NOT NULL CHECK(status IN('proposed','planned','done','cancelled')),reason TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at TEXT NOT NULL,calendar_snapshot_json TEXT NOT NULL);
CREATE TABLE work_plan_revision(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,plan_id TEXT NOT NULL,actor_id TEXT NOT NULL,occurred_at TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE work_session(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,user_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('work','leave','training')),started_at TEXT NOT NULL,ended_at TEXT,reason TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX one_open_work_session ON work_session(organization_id,user_id) WHERE ended_at IS NULL;
ALTER TABLE activity ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE activity ADD COLUMN metadata_json TEXT NOT NULL DEFAULT '{}';
CREATE TABLE visit_event(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,activity_id TEXT NOT NULL,user_id TEXT NOT NULL,event_kind TEXT NOT NULL,occurred_at TEXT NOT NULL,received_at TEXT NOT NULL,latitude_e7 INTEGER,longitude_e7 INTEGER,accuracy_cm INTEGER,source TEXT NOT NULL,quality TEXT NOT NULL,payload_json TEXT NOT NULL,UNIQUE(organization_id,id));
CREATE TABLE visit_active(organization_id TEXT NOT NULL,user_id TEXT NOT NULL,activity_id TEXT NOT NULL,started_at TEXT NOT NULL,PRIMARY KEY(organization_id,user_id),UNIQUE(activity_id));
CREATE TABLE sales_task(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,customer_id TEXT NOT NULL,user_id TEXT NOT NULL,channel TEXT NOT NULL,title TEXT NOT NULL,due_at TEXT NOT NULL,original_due_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','done','cancelled')),created_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,reason TEXT NOT NULL);
CREATE TABLE sales_handoff(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,customer_id TEXT NOT NULL,sender_id TEXT NOT NULL,receiver_id TEXT NOT NULL,channel TEXT NOT NULL,due_at TEXT NOT NULL,need TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','declined','completed','cancelled')),reason TEXT NOT NULL DEFAULT '',task_id TEXT,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sales_exception(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,customer_id TEXT,user_id TEXT NOT NULL,resource_id TEXT NOT NULL,kind TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);
CREATE TABLE sales_campaign(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,max_attempts INTEGER NOT NULL,lease_seconds INTEGER NOT NULL,hold_active_visit INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sales_script(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,campaign_id TEXT NOT NULL,name TEXT NOT NULL,content TEXT NOT NULL,qualification_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE telesales_lease(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,customer_id TEXT NOT NULL,contact_id TEXT NOT NULL,user_id TEXT NOT NULL,campaign_id TEXT NOT NULL,script_id TEXT NOT NULL,expires_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('active','completed','expired')),version INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX one_active_customer_lease ON telesales_lease(organization_id,customer_id) WHERE status='active';
CREATE TABLE call_result(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,lease_id TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL,contact_id TEXT NOT NULL,user_id TEXT NOT NULL,disposition TEXT NOT NULL,notes TEXT NOT NULL,callback_at TEXT,occurred_at TEXT NOT NULL,connection_evidence TEXT NOT NULL DEFAULT 'manual_unverified',script_snapshot_json TEXT NOT NULL,qualification_json TEXT NOT NULL);
CREATE TABLE evidence_attachment(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,activity_id TEXT NOT NULL,user_id TEXT NOT NULL,storage_key TEXT NOT NULL,size INTEGER NOT NULL,mime TEXT NOT NULL,sha256 TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
